# -*- coding: utf-8 -*-
import os
from docx import Document
from docx.shared import Inches, Pt, Cm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_ORIENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

LQ = '\u201c'  # left Chinese double quote
RQ = '\u201d'  # right Chinese double quote

def create_document(title_text, subtitle_text, paragraphs, output_path):
    doc = Document()
    
    # Page Setup
    for section in doc.sections:
        section.orientation = WD_ORIENT.PORTRAIT
        section.page_width = Cm(21.0)
        section.page_height = Cm(29.7)
        section.top_margin = Cm(2.54)
        section.bottom_margin = Cm(2.54)
        section.left_margin = Cm(3.18)
        section.right_margin = Cm(3.18)

    style = doc.styles['Normal']
    font = style.font
    font.name = '\u5b8b\u4f53'
    font.size = Pt(12)
    style.element.rPr.rFonts.set(qn('w:eastAsia'), '\u5b8b\u4f53')

    def set_paragraph_spacing(paragraph, before=0, after=4, line_spacing=1.5):
        pf = paragraph.paragraph_format
        pf.space_before = Pt(before)
        pf.space_after = Pt(after)
        pf.line_spacing = line_spacing

    # Add Title
    p_title = doc.add_paragraph()
    p_title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    set_paragraph_spacing(p_title, before=12, after=6, line_spacing=1.2)
    run_t = p_title.add_run(title_text)
    run_t.font.name = '\u9ed1\u4f53'
    run_t._element.rPr.rFonts.set(qn('w:eastAsia'), '\u9ed1\u4f53')
    run_t.font.size = Pt(16)
    run_t.bold = True

    # Add Subtitle
    if subtitle_text:
        p_sub = doc.add_paragraph()
        p_sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
        set_paragraph_spacing(p_sub, before=0, after=12, line_spacing=1.2)
        run_s = p_sub.add_run(subtitle_text)
        run_s.font.name = '\u6977\u4f53'
        run_s._element.rPr.rFonts.set(qn('w:eastAsia'), '\u6977\u4f53')
        run_s.font.size = Pt(12)
        run_s.italic = True

    # Add Body Paragraphs
    for text in paragraphs:
        p = doc.add_paragraph()
        set_paragraph_spacing(p, before=0, after=4, line_spacing=1.5)
        p.paragraph_format.first_line_indent = Cm(0.85)
        run = p.add_run(text)
        run.font.name = '\u5b8b\u4f53'
        run._element.rPr.rFonts.set(qn('w:eastAsia'), '\u5b8b\u4f53')
        run.font.size = Pt(12)

    doc.save(output_path)
    print(f"Document saved: {output_path}")

